s("plus_cardTrialEnding", "Your free month ends on {date}. Plus then continues at {price}/month unless you cancel in the store.", "Quiet Home card, last 2 days of the trial (at most once a day).", "మీ ఉచిత నెల {date}తో ముగుస్తుంది. స్టోర్‌లో రద్దు చేయకపోతే Plus నెలకు {price}తో కొనసాగుతుంది.", "Mee free month {date} tho aipotundi. Store lo cancel cheyyakapote Plus nelaki {price} tho continue avutundi.", STR("date", "price"))
s("plus_cardTrialEndingYear", "Your free month ends on {date}. Plus then continues at {price}/year unless you cancel in the store.", "Same, yearly plan.", "మీ ఉచిత నెల {date}తో ముగుస్తుంది. స్టోర్‌లో రద్దు చేయకపోతే Plus సంవత్సరానికి {price}తో కొనసాగుతుంది.", "Mee free month {date} tho aipotundi. Store lo cancel cheyyakapote Plus samvatsaraaniki {price} tho continue avutundi.", STR("date", "price"))
s("plus_cardTrialEndingNoPrice", "Your free month ends on {date}. Plus then continues unless you cancel in the store.", "Same, when no store price was captured.", "మీ ఉచిత నెల {date}తో ముగుస్తుంది. స్టోర్‌లో రద్దు చేయకపోతే Plus కొనసాగుతుంది.", "Mee free month {date} tho aipotundi. Store lo cancel cheyyakapote Plus continue avutundi.", STR("date"))
s("plus_cardKeep", "Keep Plus", "Dismisses the trial card (14-states).", "Plus ఉంచండి", "Plus unchandi")
s("plus_cardTrialCancelled", "Plus stays on until {date}. You won't be charged.", "One-time note when auto-renew is off in the trial (PRD 12).", "Plus {date} వరకు ఉంటుంది. మీకు చెల్లింపు ఉండదు.", "Plus {date} varaku untundi. Meeku charge undadu.", STR("date"))
s("plus_cardBillingIssue", "Your Aura Plus payment didn't go through. Everything you've made is safe.", "In-app banner only (PRD 12 'Billing issue').", "Aura Plus చెల్లింపు జరగలేదు. మీరు చేసినవన్నీ సురక్షితంగా ఉన్నాయి.", "Aura Plus payment jaragaledu. Meeru chesinavanni safe ga unnayi.")
s("plus_cardContinues", "Aura Plus continues. Thank you.", "One small note after the trial converts (14-states).", "Aura Plus కొనసాగుతోంది. ధన్యవాదాలు.", "Aura Plus continue avutondi. Thank you.")
s("plus_dismiss", "Dismiss", "Close a notice.", "మూసివేయండి", "Close cheyandi")

# ---- gifts + Stardust ----------------------------------------------------------
s("plus_giftWarmTea", "Warm Tea", "Gift name (₹10).", "Warm Tea", "Warm Tea")
